/**
 * Time-series pumping-test analysis (branch ws/aquascan-pumptest-timeseries, 2026-11-25).
 *
 * Worked examples:
 *  1. TTim 0.8 synthetic observation-well tests with known T and S (tests/fixtures/pumptest-benchmark.json,
 *     generated by scripts/benchmarks/pumptest_benchmark.py; independent of this code).
 *  2. Synthetic Theis datasets built HERE with an independent exponential integral E1(u)
 *     (Abramowitz & Stegun 1964, eqs 5.1.53 and 5.1.56), itself checked against the
 *     scipy.special.exp1 values in the fixture. Synthetic data, not field measurements.
 * No published textbook data set is reproduced: the stated data and answers could not be
 * verified verbatim here, so none is claimed (see docs/engineering/aquascan-pumping-test-analysis.md).
 */
import { describe, it, expect } from 'vitest';
import fx from '../fixtures/pumptest-benchmark.json';
import {
  analyzeTimeSeriesPumpTest, validateTimeSeries, parseTwoColumns, buildFieldTimeSeriesAnalysis,
  type PumpTestTimeSeries,
} from '@/external/borehole-ai-engine/src/pumpTestTimeSeries';
import { buildFieldPumpTestAnalysis } from '@/external/borehole-ai-engine/src/pumpTestAnalyzer';

// ── Independent E1(u) (A&S 5.1.53, |err| < 2e-7 for 0 < u ≤ 1; 5.1.56, |rel err| < 5e-5 for u ≥ 1) ──
function E1(u: number): number {
  if (u <= 1) {
    return -Math.log(u) - 0.57721566 + 0.99999193 * u - 0.24991055 * u ** 2 + 0.05519968 * u ** 3 - 0.00976004 * u ** 4 + 0.00107857 * u ** 5;
  }
  const num = u ** 4 + 8.5733287401 * u ** 3 + 18.059016973 * u ** 2 + 8.6347608925 * u + 0.2677737343;
  const den = u ** 4 + 9.5733223454 * u ** 3 + 25.6329561486 * u ** 2 + 21.0996530827 * u + 3.9584969228;
  return (num / den) / (u * Math.exp(u));
}
const geom = (a: number, b: number, n: number) => Array.from({ length: n }, (_, i) => Number((a * (b / a) ** (i / (n - 1))).toFixed(3)));
const theis = (Qh: number, T: number, S: number, r: number, tMin: number) => {
  if (tMin <= 0) return 0;
  const u = (r * r * S) / (4 * T * (tMin / 1440));
  return ((Qh * 24) / (4 * Math.PI * T)) * E1(u);
};
const r5 = (x: number) => Math.round(x * 1e5) / 1e5;
const rel = (a: number, b: number) => Math.abs(a - b) / Math.abs(b);

const base = (over: Partial<PumpTestTimeSeries>): PumpTestTimeSeries => ({
  rate_m3h: 20, rateChanges: [], readings: [], pumpingStopped_min: null, recovery: [],
  observationDistance_m: null, pumpIntakeDepth_m: null, staticWaterLevel_m: 12, ...over,
});

// Worked example A: observation well, T = 120 m²/day, S = 2e-4, Q = 20 m³/h, r = 30 m, 48 h pumping + 24 h recovery.
const A = { T: 120, S: 2e-4, Q: 20, r: 30, tp: 2880 };
const aTimes = geom(1, A.tp, 40);
const aRec = geom(1, 1440, 25);
const exampleA = base({
  rate_m3h: A.Q, observationDistance_m: A.r,
  readings: aTimes.map((t) => ({ t_min: t, s_m: r5(theis(A.Q, A.T, A.S, A.r, t)) })),
  pumpingStopped_min: A.tp,
  recovery: aRec.map((tp) => ({ tPrime_min: tp, sResidual_m: r5(theis(A.Q, A.T, A.S, A.r, A.tp + tp) - theis(A.Q, A.T, A.S, A.r, tp)) })),
});

describe('independent E1 used to build the synthetic data matches scipy.special.exp1', () => {
  for (const w of fx.wellFunction) {
    it(`E1(${w.u})`, () => { expect(Math.abs(E1(w.u) - w.W)).toBeLessThan(Math.max(3e-7, 6e-5 * w.W)); });
  }
});

describe('worked example A: observation well, T 120 m²/day, S 2e-4 (synthetic Theis, 48 h + 24 h recovery)', () => {
  const a = analyzeTimeSeriesPumpTest(exampleA);
  it('status analysed; Theis fit recovers T within 0.5 % and S within 1 %', () => {
    expect(a.status).toBe('analysed');
    expect(rel(a.theis!.T_m2d, A.T)).toBeLessThan(0.005);
    expect(rel(a.theis!.S!, A.S)).toBeLessThan(0.01);
    expect(a.theis!.r2).toBeGreaterThan(0.9999);
    expect(a.theis!.maxAbsResidual_m).toBeLessThan(1e-3);
    expect(a.theis!.residuals).toHaveLength(40);
  });
  it('Cooper-Jacob: u < 0.01 check met, T within 1 %, S within 5 %', () => {
    const cj = a.cooperJacob!;
    expect(cj.uCheck.met).toBe(true);
    // u < 0.01 ⇔ t > r²S/(0.04 T) = 900 × 2e-4 / 4.8 day = 0.0375 day = 54 min
    expect(cj.uCheck.validAfter_min).toBeGreaterThan(45);
    expect(cj.uCheck.validAfter_min).toBeLessThan(65);
    expect(cj.segment.from_min).toBeGreaterThan(cj.uCheck.validAfter_min);
    expect(rel(cj.T_m2d, A.T)).toBeLessThan(0.01);
    expect(rel(cj.S!, A.S)).toBeLessThan(0.05);
    expect(cj.segmentSensitivity_T_m2d[0]).toBeLessThanOrEqual(cj.T_m2d);
    expect(cj.segmentSensitivity_T_m2d[1]).toBeGreaterThanOrEqual(cj.T_m2d);
  });
  it('hand check of the Cooper-Jacob slope: Δs = 2.303 Q / (4π T) = 0.733 m per log cycle', () => {
    const expected = (2.303 * A.Q * 24) / (4 * Math.PI * A.T);
    expect(expected).toBeCloseTo(0.733, 3);
    expect(rel(a.cooperJacob!.slopePerLogCycle_m, expected)).toBeLessThan(0.01);
  });
  it('Theis recovery recovers T within 2 % and extrapolates to ~0 m at t/t\' = 1', () => {
    expect(a.recovery!.usable).toBe(true);
    expect(rel(a.recovery!.T_m2d, A.T)).toBeLessThan(0.02);
    expect(Math.abs(a.recovery!.residualAtRatio1_m)).toBeLessThan(0.02);
  });
  it('reported T = Theis fit (observation well), with the range between the three methods', () => {
    expect(a.transmissivity!.method).toBe('Theis curve fit');
    expect(a.transmissivity!.methodsRange_m2d[0]).toBeLessThanOrEqual(A.T * 1.02);
    expect(a.transmissivity!.methodsRange_m2d[1]).toBeGreaterThanOrEqual(A.T * 0.98);
    expect(a.transmissivity!.spreadPct).toBeLessThan(3);
    expect(a.transmissivity!.value_m2s).toBeCloseTo(a.transmissivity!.value_m2d / 86400, 15);
    expect(rel(a.storativity!.value, A.S)).toBeLessThan(0.01);
  });
  it('specific capacity is the measured Q / s at the end of pumping', () => {
    const last = exampleA.readings[exampleA.readings.length - 1];
    expect(a.specificCapacity!.value_m3h_per_m).toBeCloseTo(A.Q / last.s_m, 12);
  });
  it('planning estimate: drawdown projection at the tested rate, labelled, with assumptions; never a yield', () => {
    const pe = a.planningEstimate;
    expect(pe.status).toBe('presented');
    // Exact Theis at 365 days (u ≈ 1e-7): the straight line must agree within 1 %.
    const exact = theis(A.Q, A.T, A.S, A.r, 365 * 1440);
    expect(rel(pe.projectedDrawdown_m!, exact)).toBeLessThan(0.01);
    expect(pe.statement).toMatch(/^PLANNING ESTIMATE \(extrapolation, not a measured or sustainable yield\)/);
    expect(pe.assumptions.length).toBeGreaterThanOrEqual(3);
  });
  it('no verdicts or yield claims anywhere in the result', () => {
    expect(JSON.stringify(a)).not.toMatch(/good aquifer|excellent|sustainable yield (is|of)|safe yield|recommended yield|maximum continuous pumping/i);
  });
  it('deterministic', () => { expect(JSON.stringify(analyzeTimeSeriesPumpTest(exampleA))).toBe(JSON.stringify(a)); });
});

describe('worked example B: readings in the pumping well (T 40 m²/day, S 1e-3, rw 0.1 m, well loss 1.5 m)', () => {
  const B = { T: 40, S: 1e-3, Q: 6, rw: 0.1, loss: 1.5 };
  const b = analyzeTimeSeriesPumpTest(base({
    rate_m3h: B.Q, staticWaterLevel_m: 20, pumpIntakeDepth_m: 60,
    readings: geom(1, 1440, 30).map((t) => ({ t_min: t, s_m: r5(theis(B.Q, B.T, B.S, B.rw, t) + B.loss) })),
  }));
  it('storativity is NOT reported: stated as not reliably determinable', () => {
    expect(b.geometry).toBe('pumping-well');
    expect(b.storativity).toBeNull();
    expect(b.theis!.S).toBeNull();
    expect(b.cooperJacob!.S).toBeNull();
    expect(b.storativityStatement).toMatch(/not reliably determinable/);
  });
  it('reported T is Cooper-Jacob (slope only, unaffected by the constant well loss), within 1 %', () => {
    expect(b.transmissivity!.method).toBe('Cooper-Jacob straight line');
    expect(rel(b.transmissivity!.value_m2d, B.T)).toBeLessThan(0.01);
  });
  it('planning estimate compares the projection with the available drawdown to the intake (40 m)', () => {
    expect(b.planningEstimate.status).toBe('presented');
    expect(b.planningEstimate.availableDrawdown_m).toBe(40);
    expect(b.planningEstimate.statement).toMatch(/available drawdown to the pump intake is 40 m/);
  });
});

describe('noise, variable rate and short tests', () => {
  it('±1 cm deterministic noise: T within 5 % and the reported range brackets the true value', () => {
    let seed = 7;
    const noise = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return (seed / 2147483648 - 0.5) * 0.02; };
    const noisy = { ...exampleA, readings: exampleA.readings.map((x) => ({ ...x, s_m: Math.max(0, r5(x.s_m + noise())) })) };
    const a = analyzeTimeSeriesPumpTest(noisy);
    expect(rel(a.transmissivity!.value_m2d, A.T)).toBeLessThan(0.05);
    const ci = a.theis!.T_ci95_m2d!;
    expect(ci[0]).toBeLessThan(a.theis!.T_m2d);
    expect(ci[1]).toBeGreaterThan(a.theis!.T_m2d);
  });

  it('a rate change: only the first constant-rate segment is analysed, and this is stated', () => {
    const tc = 600, Q2 = 30;
    const s = (t: number) => theis(A.Q, A.T, A.S, A.r, t) + (t > tc ? theis(Q2 - A.Q, A.T, A.S, A.r, t - tc) : 0);
    const a = analyzeTimeSeriesPumpTest(base({
      rate_m3h: A.Q, observationDistance_m: A.r, rateChanges: [{ t_min: tc, rate_m3h: Q2 }],
      readings: aTimes.map((t) => ({ t_min: t, s_m: r5(s(t)) })),
      pumpingStopped_min: A.tp, recovery: exampleA.recovery,
    }));
    expect(a.variableRate!.statement).toMatch(/^Variable-rate analysis not supported: constant-rate segment analysed/);
    expect(a.analysedSegment.to_min).toBeLessThanOrEqual(tc);
    expect(rel(a.theis!.T_m2d, A.T)).toBeLessThan(0.01);
    expect(a.recovery).toBeNull();
    expect(a.recoveryNotAnalysed).toMatch(/rate changed/);
    expect(a.planningEstimate.status).toBe('withheld');
  });

  it('a rate change leaving fewer than 6 constant-rate readings: INSUFFICIENT EVIDENCE, no parameters', () => {
    const a = analyzeTimeSeriesPumpTest(base({
      rate_m3h: 5, rateChanges: [{ t_min: 4.5, rate_m3h: 8 }],
      readings: [1, 2, 3, 4, 10, 20, 40, 80].map((t, i) => ({ t_min: t, s_m: 0.5 + i * 0.3 })),
    }));
    expect(a.status).toBe('insufficient');
    expect(a.transmissivity).toBeNull();
    expect(a.storativity).toBeNull();
    expect(a.insufficientEvidence).toMatch(/^INSUFFICIENT EVIDENCE/);
    expect(a.planningEstimate.status).toBe('withheld');
  });

  it('a 6-hour test: parameters reported, planning estimate withheld (< 24 h)', () => {
    const a = analyzeTimeSeriesPumpTest({ ...exampleA, readings: exampleA.readings.filter((x) => x.t_min <= 360), recovery: [], pumpingStopped_min: null });
    expect(a.status).toBe('analysed');
    expect(a.planningEstimate.status).toBe('withheld');
    expect(a.planningEstimate.statement).toMatch(/at least 24 h/);
    expect(a.warnings.join(' ')).toMatch(/less than 24 h/);
  });

  it('a flat record (no drawdown growth): INSUFFICIENT EVIDENCE, never a fixed transmissivity', () => {
    const a = analyzeTimeSeriesPumpTest(base({ rate_m3h: 10, readings: [1, 2, 5, 10, 20, 40, 60, 120].map((t) => ({ t_min: t, s_m: 3 })) }));
    expect(a.status).toBe('insufficient');
    expect(a.transmissivity).toBeNull();
    expect(JSON.stringify(a)).not.toMatch(/"T_m2d":(250|500)\b/);
  });

  it('accelerating late drawdown (barrier-like) withholds the planning estimate', () => {
    const a = analyzeTimeSeriesPumpTest({
      ...exampleA, recovery: [], pumpingStopped_min: null,
      // barrier boundary 300 m away: image well at 600 m; the slope tends to double at late time
      readings: aTimes.map((t) => ({ t_min: t, s_m: r5(theis(A.Q, A.T, A.S, A.r, t) + theis(A.Q, A.T, A.S, 600, t)) })),
    });
    expect(a.planningEstimate.status).toBe('withheld');
    expect(a.warnings.join(' ')).toMatch(/accelerates in the last log cycle/);
  });
});

describe('TTim synthetic observation-well tests (independent model, known T and S)', () => {
  for (const t of fx.tests) {
    it(`${t.name}: T and S recovered (Theis within 1 %, Cooper-Jacob T within 3 %)`, () => {
      const a = analyzeTimeSeriesPumpTest(base({
        rate_m3h: t.Q_m3h, observationDistance_m: t.r,
        readings: t.times_min.map((m, i) => ({ t_min: m, s_m: t.drawdown_m[i] })),
      }));
      expect(rel(a.theis!.T_m2d, t.T)).toBeLessThan(0.01);
      expect(rel(a.theis!.S!, t.S)).toBeLessThan(0.01);
      expect(rel(a.cooperJacob!.T_m2d, t.T)).toBeLessThan(0.03);
      expect(rel(a.transmissivity!.value_m2d, t.T)).toBeLessThan(0.01);
      expect(rel(a.storativity!.value, t.S)).toBeLessThan(0.01);
    });
  }
});

describe('input validation: rejected with reasons, nothing clipped', () => {
  const ok = exampleA;
  const errs = (over: Partial<PumpTestTimeSeries>) => { const v = validateTimeSeries({ ...ok, ...over }); return v.ok ? [] : v.errors; };
  it('accepts the worked example', () => { expect(validateTimeSeries(ok).ok).toBe(true); });
  it.each<[string, Partial<PumpTestTimeSeries>, RegExp]>([
    ['non-monotonic time', { readings: [...ok.readings.slice(0, 5), { t_min: 1, s_m: 1 }, ...ok.readings.slice(6)] }, /times must increase/],
    ['negative drawdown', { readings: ok.readings.map((x, i) => (i === 3 ? { ...x, s_m: -0.2 } : x)) }, /negative/],
    ['zero time', { readings: [{ t_min: 0, s_m: 0 }, ...ok.readings.slice(1)] }, /greater than 0 minutes/],
    ['too few readings', { readings: ok.readings.slice(0, 5), recovery: [], pumpingStopped_min: null }, /At least 6 timed drawdown readings/],
    ['implausible rate', { rate_m3h: 900 }, /not plausible/],
    ['implausible drawdown', { readings: ok.readings.map((x, i) => (i === 3 ? { ...x, s_m: 900 } : x)) }, /not plausible/],
    ['rate change to 0', { rateChanges: [{ t_min: 100, rate_m3h: 0 }] }, /greater than 0 m³\/h/],
    ['recovery without stop time', { pumpingStopped_min: null }, /time the pump was stopped/],
    ['stop before last reading', { pumpingStopped_min: 100 }, /before the last drawdown reading/],
    ['residual larger than pumping drawdown', { recovery: ok.recovery.map((x, i) => (i === 0 ? { ...x, sResidual_m: 50 } : x)) }, /more than the largest pumping drawdown/],
    ['observation distance 0', { observationDistance_m: 0 }, /Observation-well distance/],
    ['intake above static level', { pumpIntakeDepth_m: 5, observationDistance_m: null }, /deeper than the static water level/],
    ['all-zero drawdown', { readings: ok.readings.map((x) => ({ ...x, s_m: 0 })), recovery: [], pumpingStopped_min: null }, /no drawdown to analyse/],
  ])('%s', (_n, over, msg) => { expect(errs(over).join(' ')).toMatch(msg); });
  it('analyzeTimeSeriesPumpTest refuses an invalid record (throws, no numbers)', () => {
    expect(() => analyzeTimeSeriesPumpTest({ ...ok, rate_m3h: -1 })).toThrow(/not valid/);
  });
});

describe('paste from a spreadsheet', () => {
  it('tab-separated with a header in minutes and metres, decimal comma', () => {
    const p = parseTwoColumns('Time (min)\tDrawdown (m)\n1\t0,25\n2\t0,41\n', { first: 'time', second: 'drawdown' });
    expect(p.errors).toEqual([]);
    expect(p.rows).toEqual([[1, 0.25], [2, 0.41]]);
  });
  it('comma-separated and space-separated', () => {
    expect(parseTwoColumns('1,0.25\n2, 0.41', { first: 't', second: 's' }).rows).toEqual([[1, 0.25], [2, 0.41]]);
    expect(parseTwoColumns('t s\n1 0.25\n2   0.41', { first: 't', second: 's' }).rows).toEqual([[1, 0.25], [2, 0.41]]);
  });
  it('refuses other units and malformed lines, naming the line', () => {
    expect(parseTwoColumns('Time (hours)\tDrawdown (ft)\n1\t2', { first: 'time', second: 'drawdown' }).errors.join(' ')).toMatch(/unit other than minutes and metres/);
    expect(parseTwoColumns('Time (s), level (m)\n1,2', { first: 'time', second: 'drawdown' }).errors.join(' ')).toMatch(/unit other than minutes and metres/);
    expect(parseTwoColumns('1\t2\t3\n4\tx', { first: 'time', second: 'drawdown' }).errors).toEqual([
      'Line 1: expected 2 columns (time, drawdown), found 3.', 'Line 2: "4\tx" is not two numbers.',
    ]);
  });
});

describe('single-reading safety path is unchanged', () => {
  it('a pump test without a time series still gives only the observation + INSUFFICIENT EVIDENCE', () => {
    const pt = { sustainableYieldM3Hr: 1, drawdownM: 40, testDurationHrs: 24 };
    expect(buildFieldTimeSeriesAnalysis(pt as never)).toBeUndefined();
    const out = buildFieldPumpTestAnalysis(pt, 80);
    expect(out.analysis).toBeUndefined();
    expect(out.observation?.specificCapacity_m3hr_per_m).toBeCloseTo(1 / 40, 12);
    expect(out.insufficientEvidence).toMatch(/^INSUFFICIENT EVIDENCE/);
  });
  it('a stored time series that fails validation is not analysed', () => {
    expect(buildFieldTimeSeriesAnalysis({ timeSeries: { ...exampleA, rate_m3h: 0 } })).toBeUndefined();
  });
});

describe('low-yield and dry boreholes (synthetic)', () => {
  // Low yield: 0.5 m³/h, T = 0.5 m²/day, S = 1e-3, readings in the pumping well (rw 0.1 m),
  // static level 10 m, pump intake 40 m below ground → 30 m available drawdown.
  const lowT = 0.5, lowQ = 0.5;
  const low = analyzeTimeSeriesPumpTest(base({
    rate_m3h: lowQ, staticWaterLevel_m: 10, pumpIntakeDepth_m: 40,
    readings: geom(1, 1440, 30).map((t) => ({ t_min: t, s_m: r5(theis(lowQ, lowT, 1e-3, 0.1, t)) })).filter((x) => x.s_m <= 30),
  }));
  it('T recovered within 1 %; the projection exceeds the available drawdown and says so; no positive wording', () => {
    expect(rel(low.transmissivity!.value_m2d, lowT)).toBeLessThan(0.01);
    expect(low.planningEstimate.projectedDrawdown_m!).toBeGreaterThan(30);
    expect(low.planningEstimate.statement).toMatch(/exceeds the available drawdown to the pump intake \(30 m\): on this projection the tested rate cannot be pumped continuously/);
    expect(JSON.stringify(low)).not.toMatch(/good|excellent|high transmissivity|sustainable yield (is|of)/i);
  });
  it('dry: drawdown reaching below the pump intake is rejected as implausible, not analysed', () => {
    const v = validateTimeSeries(base({
      rate_m3h: 1, staticWaterLevel_m: 10, pumpIntakeDepth_m: 20,
      readings: [1, 2, 5, 10, 20, 40].map((t, i) => ({ t_min: t, s_m: 2 + i * 2.5 })),
    }));
    expect(v.ok).toBe(false);
    expect(v.errors.join(' ')).toMatch(/more than the available drawdown to the pump intake \(10 m\)/);
  });
});
